const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var min = Math.min(w, h);
    var cx = w * 0.50;
    var cy = h * 0.52;
    var rx = Math.min(w * 0.38, h * 0.54);
    var ry = Math.min(h * 0.35, w * 0.27);

    function makeCellPoints(cx, cy, rx, ry, phase, wobble) {
      var pts = [];
      var n = 160;
      for (var i = 0; i <= n; i++) {
        var a = (Math.PI * 2 * i) / n;
        var c = Math.cos(a);
        var s = Math.sin(a);
        var px = (c >= 0 ? 1 : -1) * Math.pow(Math.abs(c), 0.60);
        var py = (s >= 0 ? 1 : -1) * Math.pow(Math.abs(s), 0.70);
        var rr = 1 + wobble * Math.sin(3 * a + phase) + wobble * 0.45 * Math.sin(5 * a + phase * 0.7);
        pts.push([cx + rx * px * rr, cy + ry * py * rr]);
      }
      pts.push(pts[0]);
      return pts;
    }

    function makeEllipsePoints(cx, cy, rx, ry, phase, wobble) {
      var pts = [];
      var n = 120;
      for (var i = 0; i <= n; i++) {
        var a = (Math.PI * 2 * i) / n;
        var rr = 1 + wobble * Math.sin(3 * a + phase) + wobble * 0.5 * Math.sin(5 * a + phase * 0.6);
        pts.push([cx + rx * Math.cos(a) * rr, cy + ry * Math.sin(a) * rr]);
      }
      pts.push(pts[0]);
      return pts;
    }

    function poly(pts) {
      var res = null;
      try {
        res = visualSdk.polyline(pts.map(function (p) { return [p[0], p[1]]; }));
      } catch (e1) {
        res = null;
      }
      if (!res || !res.length) {
        try {
          res = visualSdk.polyline(pts.map(function (p) { return { x: p[0], y: p[1] }; }));
        } catch (e2) {
          res = [];
        }
      }
      return res;
    }

    var cellOuter = makeCellPoints(cx, cy, rx, ry, 0.7, 0.012);
    var cellInner = makeCellPoints(cx, cy, rx - Math.max(10, min * 0.018), ry - Math.max(10, min * 0.018), 0.7, 0.010);
    var vx = w * 0.49;
    var vy = h * 0.60;
    var vrx = w * 0.22;
    var vry = h * 0.19;
    var vacuole = makeEllipsePoints(vx, vy, vrx, vry, 1.3, 0.035);
    var nx = w * 0.74;
    var ny = h * 0.33;
    var nr = min * 0.065;
    var ntx = nx + nr * 0.92;
    var nty = ny - nr * 0.18;

    var leaders = [];
    leaders = leaders.concat(visualSdk.arrow(w * 0.08, h * 0.25, w * 0.13, h * 0.40, { headSize: 7, strokeWidth: 2 }));
    leaders = leaders.concat(visualSdk.arrow(w * 0.86, h * 0.26, ntx, nty, { headSize: 7, strokeWidth: 2 }));
    leaders = leaders.concat(visualSdk.arrow(w * 0.86, h * 0.68, w * 0.70, h * 0.62, { headSize: 7, strokeWidth: 2 }));

    var dots = [];
    dots = dots.concat(visualSdk.circle(w * 0.13, h * 0.40, 4.5));
    dots = dots.concat(visualSdk.circle(ntx, nty, 4.5));
    dots = dots.concat(visualSdk.circle(w * 0.70, h * 0.62, 4.5));

    var labelSize = Math.max(16, Math.round(min * 0.034));

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-teaching',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'cellWall', commands: poly(cellOuter) },
        { id: 'membrane', commands: poly(cellInner) },
        { id: 'vacuole', commands: poly(vacuole) },
        { id: 'nucleus', commands: visualSdk.circle(nx, ny, nr) },
        { id: 'nucleolus', commands: visualSdk.circle(nx + nr * 0.15, ny - nr * 0.10, nr * 0.36) },
        { id: 'leaders', commands: leaders },
        { id: 'dots', commands: dots }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'cellWall', fill: '#eef8e6', stroke: '#4f7a3a', strokeWidth: 10 },
          { type: 'path', pathId: 'membrane', fill: 'none', stroke: '#8fbf6f', strokeWidth: 3 },
          { type: 'path', pathId: 'vacuole', fill: '#d9eff8', stroke: '#3f8fa8', strokeWidth: 3 },
          { type: 'path', pathId: 'nucleus', fill: '#f6d9e8', stroke: '#9c4f78', strokeWidth: 4 },
          { type: 'path', pathId: 'nucleolus', fill: '#bf6f99', stroke: '#8f4568', strokeWidth: 2 },
          { type: 'path', pathId: 'leaders', fill: 'none', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'dots', fill: '#26354a', stroke: '#26354a', strokeWidth: 1 },
          { type: 'label', text: '细胞壁', x: w * 0.075, y: h * 0.22, fill: '#1e3a2a', fontSize: labelSize, textAnchor: 'start', fontWeight: 600 },
          { type: 'label', text: '细胞核', x: w * 0.925, y: h * 0.23, fill: '#4a1f36', fontSize: labelSize, textAnchor: 'end', fontWeight: 600 },
          { type: 'label', text: '液泡', x: w * 0.925, y: h * 0.73, fill: '#1d3f52', fontSize: labelSize, textAnchor: 'end', fontWeight: 600 }
        ]
      }
    };
  }
};
